		"rev": "633ab199cfd724aa78013c006b27a2b3d049fc3b"
	},
	"watch": [
		"codex-rs/models-manager/models.json",
		"codex-rs/collaboration-mode-templates/templates",
		"codex-rs/core/src/agent/builtins",
		"codex-rs/core/src/agent/role.rs"
	],
	"shared": "shared.md",
	"profiles": {
		"codex": {
			"overlay": "codex.md",
			"upstream": [
				{
					"path": "codex-rs/models-manager/models.json",
					"symbol": "models[gpt-5.6-sol].base_instructions",
					"note": "GPT-5.6 Sol/Terra/Luna share the same base_instructions. Condensed into Pi vocabulary. Host channels, apply_patch, exec_command, and Codex skill-orchestrator protocol are dropped."
				},
				{
					"path": "codex-rs/collaboration-mode-templates/templates/default.md",
					"note": "Default collaboration mode extra. request_user_input becomes ask_user_question, used sparingly."
				}
			]
		},
		"codex-plan": {
			"overlay": "codex-plan.md",
			"upstream": [
				{
					"path": "codex-rs/collaboration-mode-templates/templates/plan.md",
					"note": "Plan collaboration mode extra. Non-mutating exploration only. Host <proposed_plan> tags and update_plan are dropped; ask_user_question covers remaining decisions."
				}
			]
		}
	}
}
{
	"family": "deepseek",
	"ref": {
		"path": "~/.ref/deepseek-harness",
		"remote": "https://github.com/deepseek-ai/deepseek-harness.git",
		"rev": "5badb15009ae1756c3afe0ae0cef1faafc290ccc"
	},
	"watch": [
		"packages/bundle/web-app/presets",
		"packages/plan/plan-mode/src/index.ts",
		"packages/core/system-prompt/src/index.ts",
		"apps/web/tests/expected/agent-preset-selection/menu.expected.md"
	],
	"shared": "shared.md",
	"profiles": {
		"deepseek-standard": {
			"overlay": "deepseek.md",
			"upstream": [
				{
					"path": "packages/bundle/web-app/presets/standard.patch.yml",
					"note": "Standard is the default full coding-agent preset. Shared omits the persona: upstream splits it into a prefix (coding agent powered by {{model}}) and a suffix (working directory {{cwd}}); Pi's opening line covers the identity, PI_* env covers the model, and Pi supplies cwd.; it keeps ground-in-repo and verified-completion. The extra keeps bash-exit, lsp_navigation, untrusted web, jobs, and background-delegation. Read/cat, grep/glob, todo, and ask-user restatements are dropped so they do not fight Pi Guidelines. Cordis composition, sandbox escalation, goals, Ralph (disabled upstream), workflow scripts, schedule reminders, present, time-context, plugin-manager, and foreign tool names stay dropped."
				},
				{
					"path": "packages/fs/tool-fs/src/read.ts",
					"symbol": "applyReadTool"
				},
				{
					"path": "packages/fs/tool-fs/src/write.ts",
					"symbol": "applyWriteTool"
				},
				{
					"path": "packages/fs/tool-fs/src/edit.ts",
					"symbol": "applyEditTool"
				},
				{
					"path": "packages/fs/tool-fs-search/src/grep.ts",
					"symbol": "applyGrepTool"
				},
				{
					"path": "packages/fs/tool-fs-search/src/glob.ts",
					"symbol": "applyGlobTool",
					"note": "glob maps to Pi find."
				},
				{
					"path": "packages/shell/tool-bash/src/index.ts",
					"note": "Check the bash result exit marker before moving on."
				},
				{
					"path": "packages/todo/tool-todo/src/index.ts",
					"symbol": "describe",
					"note": "Standard mounts allowParallelInProgress. Whole-list replace maps to Pi todo."
				},
				{
					"path": "packages/interaction/tool-ask-user/src/index.ts",
					"note": "ask_user_question is folded into the Standard parent."
				},
				{
					"path": "packages/web/tool-web/src/search.ts",
					"symbol": "applyWebSearchTool"
				},
				{
					"path": "packages/web/tool-web/src/fetch.ts",
					"symbol": "applyWebFetchTool",
					"note": "web_fetch maps to Pi fetch_content. Treat returned pages as untrusted data."
				},
				{
					"path": "packages/subagent/tool-subagent/src/index.ts",
					"note": "Background-by-default spawn maps to Pi subagent. Host fork, list-agents, Ralph, and workflow tools are dropped."
				},
				{
					"path": "packages/jobs/tool-jobs/src/index.ts",
					"note": "Do not busy-poll background work. job_output and job_kill stay host-only."
				},
				{
					"path": "packages/lsp/tool-lsp/src/index.ts",
					"symbol": "LSP_PROMPT_TEXT",
					"note": "lsp maps to Pi lsp_navigation."
				},
				{
					"path": "packages/bundle/web-app/presets/ptc.patch.yml",
					"note": "PTC is visible upstream (menu order 2) but requires the host run_code TypeScript SDK and therefore is not a Pi HarnessName; its ordinary coding discipline folds into the Standard parent."
				},
				{
					"path": "packages/bundle/web-app/presets/cordis.patch.yml",
					"note": "Creator is visible upstream (menu order 4) but its distinguishing behavior is live Cordis runtime inspection and preset self-authoring. Those host-only capabilities are dropped rather than represented as an indistinguishable Pi parent."
				},
				{
					"path": "apps/web/tests/expected/agent-preset-selection/menu.expected.md",
					"note": "CLI-visible shipped presets: Standard, PTC, Minimal, Creator. Permission presets are sandbox/approval bundles and are not parents."
				}
			]
		},
		"deepseek-plan": {
			"overlay": "deepseek-plan.md",
			"upstream": [
				{
					"path": "packages/bundle/web-app/presets/standard.patch.yml",
					"symbol": "planning / plan-mode / config.section",
					"note": "Active /plan guidance is adapted to Pi: inspect without mutation, resolve facts before asking, skip todo during planning, and produce a decision-complete final plan. exit_plan_mode and Web-only review mechanics are dropped; present the plan in the final response."
				},
				{
					"path": "packages/plan/plan-mode/README.md",
					"sections": ["Entering and leaving plan mode", "The reviewed exit", "Plan policy system prompt"]
				}
			]
		},
		"deepseek-minimal": {
			"overlay": "deepseek-minimal.md",
			"upstream": [
				{
					"path": "packages/bundle/web-app/presets/minimal.patch.yml",
					"note": "Minimal's complete helpful-engineer persona and persistent shell plus str_replace_editor surface map to Pi bash, read, write, and edit. Runtime-specific persistence, no-network claims, absolute-path requirements, and foreign editor commands are dropped. ask_user_question stays on, same as Standard."
				}
			]
		}
	}
}
{
	"family": "grok-build",
	"ref": {
		"path": "~/.ref/grok-build",
