		"crates/common/xai-tool-types/src/task.rs",
		"crates/codegen/xai-grok-pager/docs/user-guide/19-plan-mode.md"
	],
	"shared": "shared.md",
	"profiles": {
		"grok-build": {
			"overlay": null,
			"upstream": [
				{
					"path": "crates/codegen/xai-grok-agent/templates/prompt.md",
					"sections": ["work_policy", "tool_calling", "communication"],
					"note": "Parent has no prompt_body. Shared overlay is a Pi-tool-name condensation of those sections."
				},
				{
					"path": "crates/codegen/xai-grok-agent/src/config.rs",
					"symbol": "AgentDefinition::grok_build_ask_user",
					"note": "Interactive CLI injects AskUserQuestion via this hidden profile. Pi folds the tool into grok-build. Concise and orchestrator stay unnamed; they are not CLI-visible."
				}
			]
		},
		"grok-build-plan": {
			"overlay": "grok-build-plan.md",
			"upstream": [
				{
					"path": "crates/codegen/xai-grok-pager/docs/user-guide/19-plan-mode.md",
					"note": "TUI Plan session gate: inspect, write the plan, ask, do not implement. Pi has no enter/exit_plan_mode or plan.md edit gate."
				},
				{
					"path": "crates/codegen/xai-grok-agent/src/config.rs",
					"symbol": "AgentDefinition::grok_build_plan",
					"note": "Builtin is default tools plus enter/exit plan tools, not the TUI Plan cycle. Auto and Always-approve are PermissionMode only and have no parent overlay."
				}
			]
		}
	}
}
{
	"family": "qwen-code",
	"ref": {
		"path": "~/.ref/qwen-code",
		"remote": "https://github.com/QwenLM/qwen-code.git",
		"rev": "cf86aa411fb92605827cb65a03daf4ab3401507e"
	},
	"watch": [
		"packages/core/src/core/prompts.ts",
		"packages/core/src/subagents/builtin-agents.ts",
		"docs/users/features/approval-mode.md",
		"docs/users/features/sub-agents.md"
	],
	"shared": "shared.md",
	"profiles": {
		"qwen-code": {
			"overlay": null,
			"upstream": [
				{
					"path": "packages/core/src/core/prompts.ts",
					"symbol": "buildDefaultBasePrompt",
					"note": "Parent has no extra overlay. Shared is a Pi-tool-name condensation of Core Mandates, Software Engineering Tasks, tool guidance, and Executing actions with care. Host identity, sandbox, git recipes, skill new-app, absolute-path rule, enter_plan_mode, and tool-call examples are dropped."
				},
				{
					"path": "packages/core/src/core/prompts.ts",
					"symbol": "getInteractiveInteractionModePrompt",
					"note": "Interactive AskUserQuestion is folded into qwen-code. Headless never-ask wording is not imported."
				},
				{
					"path": "docs/users/features/approval-mode.md",
					"note": "Shift+Tab cycles plan → default (Ask Permissions) → auto-edit → auto → yolo. Ask Permissions, Auto-Edit, Auto, and YOLO are permission modes with no parent overlay."
				}
			]
		},
		"qwen-code-plan": {
			"overlay": "qwen-code-plan.md",
			"upstream": [
				{
					"path": "packages/core/src/core/prompts.ts",
					"symbol": "getPlanModeSystemReminder",
					"note": "TUI Plan session gate: inspect, ask, present a plan, do not implement. Pi has no enter/exit_plan_mode. Do not retry blocked writes."
				},
				{
					"path": "docs/users/features/approval-mode.md",
					"note": "Plan is read-only analysis. /plan and Shift+Tab are host chrome."
				}
			]
		}
	}
}
