			]
		},
		"zcode-plan": {
			"overlay": "zcode-plan.md",
			"upstream": [
				{
					"path": "docs/agents.md",
					"note": "Plan mode: review and propose a plan first; start editing after confirmation. Pi session is already in Plan: inspect, ask, do not implement."
				},

