	{
		match: ["openai/*", "openai-codex/*", "*/openai/*", "*/openai-codex/*", "gpt-*"],
		harness: "codex",
	},
	{
		match: ["xai/*", "x-ai/*", "*/xai/*", "*/x-ai/*", "grok-*"],
		harness: "grok-build",
	},
	{
		match: ["z-ai/*", "zai/*", "*/z-ai/*", "*/zai/*", "glm-*"],
		harness: "zcode",
	},
	{
		match: ["qwen/*", "alibaba/*", "dashscope/*", "*/qwen/*", "*/alibaba/*", "qwen*", "qwq-*"],
		harness: "qwen-code",
	},
	{
		match: ["deepseek/*", "deepseek-ai/*", "*/deepseek/*", "*/deepseek-ai/*", "deepseek-*"],
		harness: "deepseek-minimal",
	},
] as const satisfies readonly HarnessRoute[];

export const DEFAULT_HARNESS_CONFIG: HarnessConfig = {
	default: DEFAULT_HARNESS,
	routes: DEFAULT_HARNESS_ROUTES,
	grades: { ...DEFAULT_GRADES },
};

export function isHarnessName(value: string): value is HarnessName {
	return (HARNESS_NAMES as readonly string[]).includes(value);
}

export function isPiDefault(value: string): boolean {
	return value === PI_DEFAULT || value === "none" || value === "off";
}

/** `off`, plus the legacy `pi-default` / `none` spellings of the same command. */
export function isAutoOff(value: string): boolean {
	return value === AUTO_OFF || isPiDefault(value);
}

/** `/harness:name` or `/harness name` → name. */
export function parseHarnessArg(raw: string): string {
	return raw
		.trim()
		.toLowerCase()
		.replace(/^(harness:|:)/, "");
}

/** The one auto command is named for the direction it applies: `off` while routing is on, `on` while it is off. */
export function autoCommand(autoRoute: boolean | undefined): typeof AUTO_OFF | typeof AUTO_ON {
	return autoRoute === false ? AUTO_ON : AUTO_OFF;
}

export function harnessCommand(name: HarnessName | typeof PI_DEFAULT | typeof AUTO_OFF | typeof AUTO_ON): string {
	return `harness:${name}`;
}

export function harnessLabel(name: HarnessName | typeof PI_DEFAULT | typeof AUTO_OFF | typeof AUTO_ON): string {
	return harnessCommand(name);
}
