export function composeChildPrompt(input: {
	family: PromptFamily;
	rolePrompt: string;
	includesFamilyShared?: boolean;
	common?: boolean;
	root?: string;
}): { family: PromptFamily; text: string; files: string[] } {
	const rolePrompt = input.rolePrompt.trim();
	if (input.family === "pi-default") {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	const shared = familySharedBody(input.family, input.root).trim();
	const common = input.common ? commonBody(input.root).trim() : "";
	const needsCommon = Boolean(common && !rolePrompt.includes(common));
	if (input.includesFamilyShared) {
		if (needsCommon) {
			return {
				family: input.family,
				text: [rolePrompt, common].filter(Boolean).join("\n"),
				files: rolePrompt ? ["role", "common.md"] : ["common.md"],
			};
		}
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	if (!shared) {
		return {
			family: input.family,
			text: rolePrompt,
			files: rolePrompt ? ["role"] : [],
		};
	}
	if (rolePrompt.includes(shared)) {
		if (needsCommon) {
			return {
				family: input.family,
				text: [rolePrompt, common].filter(Boolean).join("\n"),
				files: [`${input.family}/shared.md`, "role", "common.md"],
			};
		}
		return {
			family: input.family,
			text: rolePrompt,
			files: [`${input.family}/shared.md`, "role"],
		};
	}
	const parts = [shared, rolePrompt];
	const files: string[] = [`${input.family}/shared.md`];
	if (rolePrompt) files.push("role");
	if (needsCommon) {
		parts.push(common);
		files.push("common.md");
	}
	const text = parts.filter(Boolean).join("\n");
	return {
		family: input.family,
		text,
		files,
	};
}

